var a=`0668-banku-and-tilapia`;var t=`world-0668`;var n=`GH`;var o=`western-africa`;var s=4;var r=85;var l={en:`Banku and Tilapia`,ua:`Банку з тиляпією`};var u={en:`Banku and Tilapia is a Ghana classic prepared with cornmeal, cassava flour, tilapia, lemon juice. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Banku-style paste made without a genuine fermented corn-cassava starter; the taste is milder than authentic banku.`,ua:`Банку з тиляпією, страва кухні країни Гана зі складниками: кукурудзяна крупа дрібного помелу, борошно маніоку, тилапія, лимонний сік. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Маса у стилі банку без справжньої ферментованої кукурудзяно-маніокової закваски; смак буде м’якшим.`};var g=[{en:`Whisk cornmeal and cassava flour with water to remove lumps before cooking the banku-style dough.`,ua:`Розмішайте кукурудзяне й маніокове борошно з водою до зникнення грудочок перед варінням тіста у стилі банку.`,t:[`mixing`],m:15,i:[[`cornmeal`,300,`g`],[`cassava-flour`,140,`g`],[`water`,880,`ml`],[`table-salt`,5,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 22 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 22 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:22,i:[]},{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 25 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 25 хвилин.`,t:[`marinating`],m:25,i:[[`tilapia`,700,`g`],[`lemon-juice`,35,`ml`],[`garlic`,4,`clove`],[`hot-paprika`,5,`g`]]},{en:`Grill over medium-high heat for about 18 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 18 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:18,i:[[`sunflower-oil`,30,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`yellow-onion`,140,`g`],[`tomato`,220,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]}];var m={slug:a,id:t,country:`GH`,region:o,servings:4,minutes:85,title:l,text:u,steps:g};export{n as country,m as default,t as id,r as minutes,o as region,s as servings,a as slug,g as steps,u as text,l as title};